create function public.log_cash_report_print(_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare c cash_checks;p profiles;begin select * into c from cash_checks where id=_id and kind='close';if not found or not coalesce(pos_shop_access(c.shop_id),false) then raise exception 'Close report unavailable';end if;select * into p from profiles where id=auth.uid();insert into audit_log(user_id,user_name,staff_code,shop_id,action,table_name,record_id,new_values,device) values(auth.uid(),p.name,p.staff_code,c.shop_id,'close_report_printed','cash_checks',c.id::text,jsonb_build_object('day',c.day,'difference',c.difference),request_device());end $$;
revoke all on function public.log_cash_report_print(uuid) from public,anon;grant execute on function public.log_cash_report_print(uuid) to authenticated;
comment on function public.log_cash_report_print(uuid) is 'Authenticated shop-scoped close report print auditing. Caller must have active shop access.';
do $$ declare definition text;begin select pg_get_functiondef('public.complete_pos_sale(uuid,text,jsonb,integer,jsonb,uuid,text,text,uuid)'::regprocedure) into definition;definition:=replace(definition,'standard:=p.selling_price;','if phone_reserved(p.id) then raise exception ''Phone is reserved by a held sale'';end if;standard:=p.selling_price;');execute definition;end $$;
insert into held_sale_phones(held_id,product_id,shop_id)
select distinct on(p.id) h.id,p.id,h.shop_id from held_sales h cross join lateral jsonb_array_elements(h.cart->'items') x join products p on p.id=(x->>'id')::uuid
where h.status='held' and h.expires_at>now() and x->>'kind'='phone' and p.status='in_stock' and p.current_shop_id=h.shop_id and not exists(select 1 from held_sale_phones r where r.product_id=p.id and r.released_at is null) order by p.id,h.created_at;
create or replace function public.guard_held_phone() returns trigger language plpgsql security definer set search_path=public as $$ begin if (new.status is distinct from old.status or new.current_shop_id is distinct from old.current_shop_id) and phone_reserved(old.id) then raise exception 'Phone is reserved by a held sale';end if;return new;end $$;